+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.Locale;
+import java.util.Set;
+
+/**
+ * The criteria used when looking up customers.
+ *
+ * <p>Keeping the criteria as a value object makes it possible for the UI to
+ * pass it all the way to the paged backend without materialising the customer
+ * data in the browser or in the service layer.
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public CustomerFilter {
+        name = name == null ? "" : name;
+        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
+    }
+
+    /** A filter which includes every customer. */
+    public static CustomerFilter empty() {
+        return new CustomerFilter("", Set.of());
+    }
+
+    /** Whether this customer's name and status meet both selected criteria. */
+    public boolean matches(Customer customer) {
+        return matchesName(customer) && (statuses.isEmpty() || statuses.contains(customer.status()));
+    }
+
+    /** Whether the name part has at least one meaningful search term. */
+    public boolean hasNameTerms() {
+        return !terms().isEmpty();
+    }
+
+    private boolean matchesName(Customer customer) {
+        String firstName = normalize(customer.firstName());
+        String lastName = normalize(customer.lastName());
+        return terms().stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    private Set<String> terms() {
+        String trimmed = name.trim();
+        if (trimmed.isEmpty()) {
+            return Set.of();
+        }
+        return Arrays.stream(trimmed.split("\\s+"))
+                .map(CustomerFilter::normalize)
+                .collect(java.util.stream.Collectors.toUnmodifiableSet());
+    }
+
+    private static String normalize(String value) {
+        return Normalizer.normalize(value, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "")
+                .toLowerCase(Locale.ROOT);
+    }
+}
